VALUES
  -- What a prioritization question is actually asking
  ('65000000-0000-4000-8000-000000000001', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'What a prioritization question is actually asking',
   'Read the question before you read the patients',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Most marks lost on prioritization are not lost on the patients. They are lost in the first line of the question, because the candidate decided what was being asked before they read it."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Sickest or healthiest?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Every prioritization item wants one of two things: the patient who needs you most, or the patient who needs you least. The words change; the fork does not."}]}, {"type": "lab_values", "attrs": {"title": "Which end of the list is the answer?", "columns": [{"label": "The question says"}, {"label": "You are looking for"}], "rows": [["Who do you see first / assess first / attend to first", "The HIGHEST priority patient"], ["Who is most at risk / whose condition is most urgent", "The HIGHEST priority patient"], ["Who do you discharge to make room / who can wait", "The LOWEST priority patient"], ["Which patient can be assigned to the LPN / the float nurse", "The LOWEST priority — the most stable patient"], ["Who do you delegate to the UAP", "The LOWEST priority — stable, predictable, no assessment"]]}}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "A disaster has struck and you are clearing beds. That question is asking for your "}, {"type": "text", "text": "healthiest", "marks": [{"type": "bold"}]}, {"type": "text", "text": " patient. Candidates who have drilled 'sickest first' answer it backwards at speed."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The four parts of an answer choice"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Answer choices in this section are built the same way every time. Learn the parts and you can strip a choice down in about two seconds."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A 10-year-old male with hypospadias who is vomiting bile-stained emesis.", "marks": [{"type": "bold"}]}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Age", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — 10-year-old"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Gender", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — male"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Diagnosis", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — hypospadias"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Modifying phrase", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — vomiting bile-stained emesis"}]}]}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Two of those four are noise. Age and gender do not decide priority in an adult medical-surgical question — they matter in paediatrics and obstetrics, and almost nowhere else."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The modifying phrase outranks the diagnosis"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This is the single highest-yield sentence in this course. When a choice carries a modifying phrase, that phrase — not the diagnosis — decides the priority."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Two patients, no modifying phrases: one has angina pectoris, one has had a myocardial infarction. The MI is the priority, because with nothing else to go on you judge by the condition."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Now add the phrases:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A patient with "}, {"type": "text", "text": "angina", "marks": [{"type": "bold"}]}, {"type": "text", "text": " and an "}, {"type": "text", "text": "unstable blood pressure", "marks": [{"type": "bold"}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A patient with "}, {"type": "text", "text": "MI", "marks": [{"type": "bold"}]}, {"type": "text", "text": " and "}, {"type": "text", "text": "stable vital signs", "marks": [{"type": "bold"}]}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The angina patient is now the priority. The lesser diagnosis with the worse modifier beats the greater diagnosis that has settled."}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Cover the diagnosis with your finger and read only the modifying phrases. If one of them describes something changing, unexpected, or unstable, you have very likely found your answer."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Where this sits against ABC and Maslow"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ABC and Maslow are frameworks for choosing between needs. The four rules in the next module are for choosing between patients. They are not competitors — a question usually needs both, in that order: find the patient, then decide what to do for them."}]}, {"type": "callout", "attrs": {"tone": "note"}, "content": [{"type": "text", "text": "If two patients survive every rule in this course and you still cannot separate them, fall back to ABC — airway, then breathing, then circulation — and only then to Maslow."}]}]}$j$::jsonb,
   ARRAY['prioritization', 'exam-strategy', 'high-yield']::text[], ARRAY['Management of Care']::text[], TRUE, 'TUTOR_WIDE'),
  -- The four prioritization rules
  ('65000000-0000-4000-8000-000000000002', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'The four prioritization rules',
   'Acute, fresh post-op, unstable — and the tie-breaker',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Four rules, applied in order. Most questions are settled by the first three; the fourth exists for the ones that are not."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Rule 1 — acute beats chronic"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "An acutely ill patient outranks a chronically ill one. Chronic disease is a condition the body has already adapted to; acute illness is the body failing to."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Given COPD, heart failure and appendicitis, the appendicitis is your patient. The other two are chronic — however unwell they sound, they are the state their body has been living in."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Rule 2 — fresh post-op beats medical and other surgical"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Fresh means "}, {"type": "text", "text": "under 12 hours", "marks": [{"type": "bold"}]}, {"type": "text", "text": ". Within that window the patient is still coming out of anaesthesia, still at risk of haemorrhage, and still the least predictable person on the ward."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A patient two hours after a cholecystectomy outranks the COPD patient, the acute appendicitis, the radical neck dissection from yesterday, the bilateral above-knee amputation from yesterday, and the craniotomy from yesterday. The size of the other operation is not the point — the clock is."}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Twelve hours is the line. At 11 hours post-op the patient is fresh and unstable; at 13 they are a surgical patient like any other. Exam items are written around that boundary deliberately."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Rule 3 — unstable beats stable"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The largest of the four, and the one with the most vocabulary attached to it. It has its own note — see "}, {"type": "text", "text": "Stable or unstable: the word list", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — because recognising instability from a phrase is most of the work."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "In short: anything acute, changing, unexpected, newly admitted, newly diagnosed or freshly operated on points to unstable. Anything chronic, unchanged, expected, or heading for discharge points to stable."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Rule 4 — the tie-breaker: how vital is the organ?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "When the first three rules leave you with two patients who look equally sick, rank by the organ involved. The more vital the organ, the higher the priority."}]}, {"type": "lab_values", "attrs": {"title": "Organ priority, most vital first", "columns": [{"label": "Rank"}, {"label": "Organ"}], "rows": [["1", "Brain"], ["2", "Lung"], ["3", "Heart"], ["4", "Liver"], ["5", "Kidney"], ["6", "Pancreas"]]}}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Rank the organ named in the "}, {"type": "text", "text": "modifying phrase", "marks": [{"type": "bold"}]}, {"type": "text", "text": ", not the organ in the diagnosis. This is where the rule is most often applied backwards."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Worked example"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Three patients. Apply rules 1 to 3 first, then the tie-breaker."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A 23-year-old with "}, {"type": "text", "text": "heart failure", "marks": [{"type": "bold"}]}, {"type": "text", "text": " (chronic — low), potassium 6.6 (high), no ECG changes (unchanged — low). Organ in the modifier: "}, {"type": "text", "text": "heart", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Chronic renal failure (chronic — low), creatinine 24.7 (expected for the diagnosis — low), "}, {"type": "text", "text": "pink frothy sputum", "marks": [{"type": "bold"}]}, {"type": "text", "text": " (unexpected — high). Organ in the modifier: "}, {"type": "text", "text": "lung", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Acute hepatitis (acute — high), jaundice and raised ammonia (both expected — low), "}, {"type": "text", "text": "cannot be roused", "marks": [{"type": "bold"}]}, {"type": "text", "text": " (unexpected — high). Organ in the modifier: "}, {"type": "text", "text": "brain", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "All three have something unexpected, so rule 3 does not separate them. The tie-breaker does: brain outranks lung outranks heart. The hepatitis patient who cannot be roused is your answer."}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Brain, Lung, Heart, Liver, Kidney, Pancreas. The order is the answer to more tie-breaks than any other single fact in this course."}]}]}$j$::jsonb,
   ARRAY['prioritization', 'high-yield', 'framework']::text[], ARRAY['Management of Care']::text[], TRUE, 'TUTOR_WIDE'),
  -- Stable or unstable: the word list
  ('65000000-0000-4000-8000-000000000003', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'Stable or unstable: the word list',
   'The vocabulary that decides rule 3',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Rule 3 says unstable beats stable. The exam almost never uses either word — it describes the patient and expects you to classify them. This is that vocabulary."}]}, {"type": "lab_values", "attrs": {"title": "What the words are telling you", "columns": [{"label": "Points to STABLE"}, {"label": "Points to UNSTABLE"}], "rows": [["Chronic illness", "Acute illness"], ["Post-op more than 12 hours", "Post-op less than 12 hours"], ["Local or regional anaesthesia", "General anaesthesia, first 12 hours"], ["Admitted longer than 24 hours", "Admitted less than 24 hours, newly admitted"], ["Ready for discharge, to be discharged", "Newly diagnosed, not ready for discharge"], ["Unchanged assessment", "Changed or changing assessment"], ["The expected signs of their diagnosis", "Unexpected signs for their diagnosis"], ["Lab values mildly off — creatinine, BUN, bicarbonate, haemoglobin 8–11, raised haematocrit, raised BNP, raised sodium", "Lab values dangerously off — INR in the 4s, potassium in the 6s, pH in the 6s, CO₂ in the 50s, low O₂ saturation, high WBC, low ANC, low CD4, low platelets"]]}}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Expected versus unexpected does more work than any other row in that table. A crushing chest pain in angina is expected and therefore stable. The same pain in a patient admitted for a fractured wrist is unexpected, and they are now your priority."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Worked example"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Which patient is the higher priority?"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A 16-year-old with meningococcal meningitis, temperature 103.8 °F, unchanged since admission three days ago."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A 67-year-old with irritable bowel syndrome who spiked a temperature of 103.4 °F this afternoon."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The 67-year-old. Line by line:"}]}, {"type": "lab_values", "attrs": {"title": "Scoring the two patients", "columns": [{"label": ""}, {"label": "16-year-old"}, {"label": "67-year-old"}], "rows": [["Diagnosis", "Meningitis — acute, HIGH", "IBS — chronic, low"], ["Temperature", "Expected for meningitis, low", "Unexpected for IBS, HIGH"], ["Trend", "Unchanged for 3 days, low", "Spiked, changing, HIGH"], ["Timing", "Admitted 3 days ago, low", "This afternoon, HIGH"]]}}, {"type": "paragraph", "content": [{"type": "text", "text": "The lower temperature belongs to the sicker patient, because three of four signals point at instability. The frightening diagnosis belongs to the patient whose body is doing exactly what that diagnosis does."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Four things that are always unstable"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "These override 'expected'. If the patient has one of these, they are unstable no matter how well it fits their diagnosis."}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Haemorrhage", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — not the same as bleeding"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fever above 105 °F", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — seizure risk"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hypoglycaemia", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — brain injury risk"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pulseless or breathless", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — ventricular fibrillation, asystole"}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "The exception that catches people: at the scene of an unwitnessed accident, a pulseless and breathless casualty is the LOWEST priority. In the field, with no witness to the arrest, they are presumed dead."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Mass casualty: the black tag"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "In a mass-casualty incident, three findings mean a black tag — expectant, treated last:"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pulseless"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Breathless"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fixed and dilated pupils, even if they are still breathing"}]}]}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Tag them black and ship them last. Triage inverts your instincts: resources go to those who can be saved, not to those who need the most."}]}]}$j$::jsonb,
   ARRAY['prioritization', 'stability', 'high-yield']::text[], ARRAY['Management of Care']::text[], TRUE, 'TUTOR_WIDE'),
  -- What you can hand to an LPN, a UAP, and a family member
  ('65000000-0000-4000-8000-000000000004', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'What you can hand to an LPN, a UAP, and a family member',
   'The three delegation boundaries, in the order the exam tests them',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Delegation questions are free marks, because the boundaries are fixed and short. Learn what each role cannot do, and the answer falls out."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The LPN / LVN — nine things they cannot do"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Start an IV"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hang or mix IV medications"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Give IV push medications"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Administer blood, or handle central lines — including flushes and dressing changes"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Create the care plan (they can implement one)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Perform or develop teaching (they can reinforce teaching already given)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Care for an unstable patient"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Perform the first of anything"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Assess on admission, discharge, transfer, or first after a change"}]}]}]}, {"type": "callout", "attrs": {"tone": "note"}, "content": [{"type": "text", "text": "An LPN may maintain an IV that is already running and document the flow. Maintaining is not starting."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "\"The first of anything\""}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This is rule 8, and it is worth its own section because it generates so many items. The registered nurse does it once; after that the LPN may repeat it."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "First tube feeding — RN. Every one after that — LPN."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "First post-op dressing change — RN. Subsequent changes — LPN."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "First feeding of a stroke patient — RN. Later feeds — LPN."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "First time a post-op patient is ambulated or got out of bed — RN."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "First set of post-op vital signs — RN."}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "So: should the LPN change the first post-operative dressing on the day of surgery? No. Two rules forbid it — it is the first of something, and the patient is fresh post-op and therefore unstable."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The UAP — four things they cannot do"}]}, {"type": "lab_values", "attrs": {"title": "Unlicensed assistive personnel", "columns": [{"label": "Cannot"}, {"label": "Except"}], "rows": [["Chart about the patient", "They may chart what they did — 'side rail up, bed lowered'. Never 'patient less anxious' or 'tolerated ambulation well'."], ["Give medications", "Topical, over-the-counter and barrier preparations only. A&D ointment yes; nitroglycerin, Neosporin and hydrocortisone cream no — none of those is OTC."], ["Assess", "Vital signs and blood-glucose checks only."], ["Perform treatments", "Enemas only."]]}}, {"type": "paragraph", "content": [{"type": "text", "text": "A UAP may carry out activities of daily living — but never the first time one is done for that patient."}]}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "The verbs give it away. Assess, teach, evaluate, plan and administer belong to the RN. Assist, remind, collect, record and transport can go to the UAP."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Family and visitors"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Safety is never delegated to a family member or visitor who has not been taught."}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Leave Dad's restraints off — I'll call you before I go.\" "}, {"type": "text", "text": "No.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Safety cannot be handed to an untrained person."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Leave the crib rail down, I'll put it up when I've finished bathing the baby.\" "}, {"type": "text", "text": "No", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — and the answer is not a lecture. Stay in the room until the rail is up."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Can I give my three-year-old his insulin?\" "}, {"type": "text", "text": "Yes", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — once you have taught them and documented exactly what you taught."}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "The pattern: an untrained family member cannot hold a safety responsibility, but a TAUGHT family member can. Teaching plus documentation is what converts a wrong answer into a right one."}]}]}$j$::jsonb,
   ARRAY['delegation', 'scope-of-practice', 'high-yield']::text[], ARRAY['Management of Care']::text[], TRUE, 'TUTOR_WIDE'),
  -- When a colleague does something wrong
  ('65000000-0000-4000-8000-000000000005', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'When a colleague does something wrong',
   'Four possible responses, and the two questions that pick between them',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "This is neither prioritization nor delegation. It is what you do when a member of staff has done something they should not have. The exam offers the same four responses almost every time."}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tell the supervisor"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Confront them and take over the task immediately"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Talk to them about it later"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ignore it"}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Ignore it is never correct. Every incident is an opportunity to correct behaviour — if the choice is 'take no action', it is wrong."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Two questions choose between the other three"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Is it illegal?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " If yes — tell the supervisor."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Is anyone in immediate physical or psychological harm?", "marks": [{"type": "bold"}]}, {"type": "text", "text": " If yes — confront and take over the task now."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If neither applies and the behaviour is merely unprofessional, speak to that person later, in private."}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "If an act is both illegal and actively harming the patient, do both — take over the task first, then report it. The patient comes before the paperwork."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Worked examples"}]}, {"type": "lab_values", "attrs": {"title": "What would you do?", "columns": [{"label": "Situation"}, {"label": "Response"}, {"label": "Why"}], "rows": [["You suspect an RN is diverting narcotics", "Tell the supervisor", "Illegal"], ["An RN leaves the ward with bulging pockets", "Tell the supervisor", "Illegal"], ["An aide gives perineal care without gloves", "Confront and take over", "Immediate harm, not illegal"], ["A surgeon contaminates her gloves", "Confront and take over", "Immediate harm, not illegal"], ["A colleague says 'exasperation' instead of 'exacerbation' in every handover", "Talk to them later", "Unprofessional, nobody is at risk"]]}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Two patients, one door"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You find two patients having sex, or a patient masturbating in their own room. Close the door and give them privacy. Adults are entitled to it, and there is no safety issue to answer."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The worst-consequences game"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "For 'which is the priority' items about needs rather than patients, ask what happens if you do not do each one. The worst outcome is your answer."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A suicidal patient has been admitted. Which is the priority?"}]}, {"type": "lab_values", "attrs": {"title": "If you skipped it, what happens?", "columns": [{"label": "Action omitted"}, {"label": "Consequence"}], "rows": [["Do not give the tranquilliser", "Agitated"], ["Do not orient them to the unit", "Lost"], ["Do not place them on suicide precautions", "DEAD"], ["Do not introduce them to staff", "Knows nobody"]]}}, {"type": "paragraph", "content": [{"type": "text", "text": "Suicide precautions. The other three have consequences; only one of them is fatal."}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Do not ask which action is most important. Ask which omission does the most damage. The answer arrives faster and it is right more often."}]}]}$j$::jsonb,
   ARRAY['staff-management', 'delegation', 'high-yield']::text[], ARRAY['Management of Care']::text[], TRUE, 'TUTOR_WIDE')
ON CONFLICT (note_id) DO UPDATE SET
  title = EXCLUDED.title, subtitle = EXCLUDED.subtitle,
  body = EXCLUDED.body, tags = EXCLUDED.tags,
  pillars = EXCLUDED.pillars, is_published = TRUE,
  version_id = gen_random_uuid(), updated_at = NOW();

