-- items NCLEX_TUT_MCQ_00101 .. NCLEX_TUT_MCQ_00105
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks)
VALUES
  ('NCLEX_TUT_MCQ_00101', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A tornado has struck the town and the charge nurse is asked to free up medical-surgical beds for incoming casualties. Which client should the nurse identify as the most appropriate to discharge?',
   'The question asks who can LEAVE, so it is looking for the lowest-priority — the most stable — client. Chronic COPD with an unchanged saturation over three days is stable on every count: chronic diagnosis, unchanged assessment, admitted longer than 24 hours. The other three are all acute, fresh post-op, or newly changed.',
   $j${"options": [{"id": "A", "text": "A client admitted 4 hours ago with new-onset atrial fibrillation"}, {"id": "B", "text": "A client 6 hours after an open cholecystectomy"}, {"id": "C", "text": "A client with long-standing COPD whose oxygen saturation has been 92% on room air since admission three days ago"}, {"id": "D", "text": "A client with pneumonia who spiked a temperature of 39.4 °C this morning"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — new-onset within 4 hours is acute and changing.", "B": "Incorrect — fresh post-op, under 12 hours. The least dischargeable client on the unit.", "C": "Correct — chronic, unchanged, and settled for three days.", "D": "Incorrect — a newly spiked fever is a changed assessment."}}$j$::jsonb,
   'Prioritization', 'Reading the question', 'Medium',
   ARRAY['prioritization', 'discharge', 'triage']::text[], 1),
  ('NCLEX_TUT_MCQ_00102', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse receives the end-of-shift handover for four clients. Which client should the nurse assess first?',
   '''Assess first'' asks for the highest priority. Numbness distal to a fracture is unexpected and suggests compartment syndrome or neurovascular compromise — a new, changing finding in a limb that can be lost. Jaundice and ascites are expected in cirrhosis; unchanged peak flow is stable; routine analgesia is not urgent.',
   $j${"options": [{"id": "A", "text": "A 58-year-old female with cirrhosis who has jaundice and ascites"}, {"id": "B", "text": "A 44-year-old male with a fractured tibia who reports his toes feel numb"}, {"id": "C", "text": "A 71-year-old female with osteoarthritis requesting her routine analgesia"}, {"id": "D", "text": "A 30-year-old male with asthma whose peak flow is unchanged from admission"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — both findings are expected in cirrhosis.", "B": "Correct — an unexpected neurovascular change after a fracture.", "C": "Incorrect — comfort matters, but nothing here is deteriorating.", "D": "Incorrect — unchanged is the definition of stable."}}$j$::jsonb,
   'Prioritization', 'Reading the question', 'Medium',
   ARRAY['prioritization', 'assessment']::text[], 1),
  ('NCLEX_TUT_MCQ_00103', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Which client should the nurse see first?',
   'New confusion two days after a thyroidectomy is unexpected and may signal thyroid storm. Crushing substernal pain is the textbook presentation of angina — unpleasant, but expected for that diagnosis. The exam repeatedly pairs a dramatic-but-expected symptom against a quiet-but-unexpected one.',
   $j${"options": [{"id": "A", "text": "A client with angina pectoris reporting crushing substernal chest pain"}, {"id": "B", "text": "A client two days after a subtotal thyroidectomy who asks the nurse 'why are they watching elephants in here?'"}, {"id": "C", "text": "A client with type 2 diabetes whose morning glucose was 9.1 mmol/L"}, {"id": "D", "text": "A client with a chronic venous ulcer due for a dressing change"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — crushing substernal pain is what angina does. Expected.", "B": "Correct — new confusion post-thyroidectomy suggests thyroid storm.", "C": "Incorrect — a mildly raised glucose is expected in type 2 diabetes.", "D": "Incorrect — a chronic wound with routine care scheduled."}}$j$::jsonb,
   'Prioritization', 'Expected vs unexpected', 'Hard',
   ARRAY['prioritization', 'endocrine']::text[], 1),
  ('NCLEX_TUT_SATA_00101', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'A nurse is analysing the answer choices in a prioritization item. Which elements of a choice should the nurse recognise as relevant to deciding priority in an adult medical-surgical question? Select all that apply.',
   'In an adult medical-surgical item the modifying phrase carries the most weight, the diagnosis matters when no modifier is present, and whether a finding is expected decides stability. Age and gender are relevant in paediatric and obstetric questions, not in general adult prioritization.',
   $j${"options": [{"id": "A", "text": "The modifying phrase describing the client's current condition"}, {"id": "B", "text": "The client's age"}, {"id": "C", "text": "The client's gender"}, {"id": "D", "text": "The medical diagnosis"}, {"id": "E", "text": "Whether the described finding is expected for that diagnosis"}]}$j$::jsonb,
   $j${"answers": ["A", "D", "E"], "feedback": {"A": "Correct — the modifying phrase outranks everything else.", "B": "Incorrect — age decides priority in paediatrics, not here.", "C": "Incorrect — gender is almost never the deciding factor.", "D": "Correct — the diagnosis decides when no modifying phrase is given.", "E": "Correct — expected findings point to stability."}}$j$::jsonb,
   'Prioritization', 'Anatomy of an answer choice', 'Medium',
   ARRAY['prioritization', 'exam-strategy']::text[], 3),
  ('NCLEX_TUT_MCQ_00104', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Two clients are admitted to a cardiac unit. Neither record contains any further detail. Which client has the higher priority?',
   'With no modifying phrase attached to either client, judge by the condition itself. Infarction means muscle is dying; angina means muscle is ischaemic but still viable. Where the exam gives you nothing else, it wants you to rank the diagnoses.',
   $j${"options": [{"id": "A", "text": "The client with angina pectoris"}, {"id": "B", "text": "The client with a myocardial infarction"}, {"id": "C", "text": "Neither — priority cannot be determined without vital signs"}, {"id": "D", "text": "Both are equal priority until assessed"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — angina is the lesser of the two conditions here.", "B": "Correct — with no modifiers, the more severe diagnosis wins.", "C": "Incorrect — the item is answerable as written.", "D": "Incorrect — MI and angina are not equivalent."}}$j$::jsonb,
   'Prioritization', 'Diagnosis vs modifier', 'Easy',
   ARRAY['prioritization', 'cardiac']::text[], 1),
  ('NCLEX_TUT_MCQ_00105', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Which client should the charge nurse assign to a newly floated nurse who does not know the unit?',
   'Assigning to an inexperienced or unfamiliar nurse is a ''who is the LOWEST priority'' question in disguise — you want the most stable client. Heart failure awaiting discharge is chronic, unchanged and leaving. The other three are fresh post-op or newly admitted.',
   $j${"options": [{"id": "A", "text": "A client 3 hours after a total hip replacement"}, {"id": "B", "text": "A client with heart failure awaiting discharge later today"}, {"id": "C", "text": "A client admitted an hour ago with acute pancreatitis"}, {"id": "D", "text": "A client with a new tracheostomy created this morning"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — fresh post-op, under 12 hours.", "B": "Correct — chronic and stable enough to be going home.", "C": "Incorrect — admitted under an hour ago; acute.", "D": "Incorrect — a new airway is the least stable client here."}}$j$::jsonb,
   'Prioritization', 'Reading the question', 'Medium',
   ARRAY['prioritization', 'assignment']::text[], 1)
