-- items NCLEX_TUT_MCQ_00106 .. NCLEX_TUT_SATA_00102
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks)
VALUES
  ('NCLEX_TUT_MCQ_00106', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse is assigned four clients. Applying the rule that acute conditions outrank chronic ones, which client should the nurse see first?',
   'Appendicitis is the only acute condition listed. COPD, chronic heart failure and osteoarthritis are all chronic — states the body has already adapted to.',
   $j${"options": [{"id": "A", "text": "A client with COPD"}, {"id": "B", "text": "A client with chronic heart failure"}, {"id": "C", "text": "A client with acute appendicitis"}, {"id": "D", "text": "A client with osteoarthritis"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — chronic.", "B": "Incorrect — chronic.", "C": "Correct — the only acute process here, and one that can perforate.", "D": "Incorrect — chronic."}}$j$::jsonb,
   'Prioritization', 'Rule 1 — acute beats chronic', 'Easy',
   ARRAY['prioritization', 'four-rules']::text[], 1),
  ('NCLEX_TUT_MCQ_00107', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Which client should the nurse assess first?',
   'Fresh post-op means under 12 hours, and it outranks other surgical clients regardless of how major their operation was. All three alternatives are more than 12 hours out and therefore comparatively stable; the 2-hour client is still emerging from anaesthesia and at highest risk of haemorrhage.',
   $j${"options": [{"id": "A", "text": "A client 2 hours after a cholecystectomy"}, {"id": "B", "text": "A client who had a radical neck dissection yesterday"}, {"id": "C", "text": "A client who had a bilateral above-knee amputation yesterday"}, {"id": "D", "text": "A client who had a right frontal craniotomy yesterday"}]}$j$::jsonb,
   $j${"answer": "A", "feedback": {"A": "Correct — 2 hours post-op. Fresh beats big.", "B": "Incorrect — yesterday. Major, but past the 12-hour window.", "C": "Incorrect — yesterday, however dramatic the surgery.", "D": "Incorrect — yesterday. The brain does not override the clock here."}}$j$::jsonb,
   'Prioritization', 'Rule 2 — fresh post-op', 'Medium',
   ARRAY['prioritization', 'four-rules', 'post-op']::text[], 1),
  ('NCLEX_TUT_MCQ_00108', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse must choose between two clients who are equally unstable. One has pink frothy sputum; the other has a potassium of 6.6 mmol/L. Using the tie-breaker rule, which client is the priority and why?',
   'The tie-breaker ranks by how vital the organ named in the MODIFYING PHRASE is: brain, lung, heart, liver, kidney, pancreas. Frothy sputum is a lung finding; a potassium of 6.6 is a cardiac risk. Lung outranks heart.',
   $j${"options": [{"id": "A", "text": "The client with frothy sputum, because the lung outranks the heart"}, {"id": "B", "text": "The client with the raised potassium, because the heart outranks the lung"}, {"id": "C", "text": "The client with frothy sputum, because respiratory problems are always first"}, {"id": "D", "text": "The client with the raised potassium, because electrolytes are life-threatening"}]}$j$::jsonb,
   $j${"answer": "A", "feedback": {"A": "Correct — lung sits above heart in the organ hierarchy.", "B": "Incorrect — the order is brain, lung, heart. Heart is third.", "C": "Incorrect — right client, wrong reason. It is the hierarchy, not a blanket rule about breathing.", "D": "Incorrect — a raised potassium is dangerous, but the lung ranks higher."}}$j$::jsonb,
   'Prioritization', 'Rule 4 — organ tie-breaker', 'Hard',
   ARRAY['prioritization', 'four-rules', 'tie-breaker']::text[], 1),
  ('NCLEX_TUT_SN_00101', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SELECT_N',
   'Place the organs in order of priority when applying the tie-breaker rule. Select the two organs that rank HIGHEST.',
   'The order is brain, lung, heart, liver, kidney, pancreas. The two highest-ranking are brain and lung.',
   $j${"options": [{"id": "A", "text": "Brain"}, {"id": "B", "text": "Kidney"}, {"id": "C", "text": "Lung"}, {"id": "D", "text": "Pancreas"}, {"id": "E", "text": "Liver"}, {"id": "F", "text": "Heart"}], "select_count": 2}$j$::jsonb,
   $j${"answers": ["A", "C"], "feedback": {"A": "Correct — the brain ranks first.", "B": "Incorrect — kidney is fifth.", "C": "Correct — the lung ranks second.", "D": "Incorrect — pancreas is last.", "E": "Incorrect — liver is fourth.", "F": "Incorrect — heart is third, just below the lung."}}$j$::jsonb,
   'Prioritization', 'Rule 4 — organ tie-breaker', 'Medium',
   ARRAY['prioritization', 'four-rules']::text[], 2),
  ('NCLEX_TUT_MCQ_00109', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Three clients each have an unexpected finding. Which should the nurse see first?',
   'Rules 1 to 3 do not separate the first three — each has something unexpected. The tie-breaker does. The modifying phrases name the heart (potassium), the lung (frothy sputum) and the brain (cannot be roused). Brain wins. Option D''s glucose is expected in type 1 diabetes.',
   $j${"options": [{"id": "A", "text": "A client with chronic heart failure, potassium 6.6 mmol/L, no ECG changes"}, {"id": "B", "text": "A client with chronic renal failure, creatinine 24.7 mg/dL, with pink frothy sputum"}, {"id": "C", "text": "A client with acute hepatitis, jaundice and raised ammonia, who cannot be roused"}, {"id": "D", "text": "A client with type 1 diabetes whose glucose is 11.2 mmol/L before breakfast"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — heart is third in the hierarchy.", "B": "Incorrect — lung is second. Close, but the brain outranks it.", "C": "Correct — an unrousable client is a brain finding, and brain ranks first.", "D": "Incorrect — a pre-breakfast glucose of 11.2 is expected here."}}$j$::jsonb,
   'Prioritization', 'Rule 4 — organ tie-breaker', 'Hard',
   ARRAY['prioritization', 'four-rules']::text[], 1),
  ('NCLEX_TUT_SATA_00102', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which findings would move a client into the higher-priority group under the four prioritization rules? Select all that apply.',
   'General anaesthesia within 12 hours, a changing assessment, admission under 24 hours and a dangerously deranged lab value all point to instability. A twelve-year history is chronic, and a client leaving today is by definition stable enough to go.',
   $j${"options": [{"id": "A", "text": "The client had a general anaesthetic 6 hours ago"}, {"id": "B", "text": "The client has had rheumatoid arthritis for twelve years"}, {"id": "C", "text": "The client's assessment has changed since the last round"}, {"id": "D", "text": "The client was admitted 40 minutes ago"}, {"id": "E", "text": "The client is being discharged this afternoon"}, {"id": "F", "text": "The client has an INR of 4.2"}]}$j$::jsonb,
   $j${"answers": ["A", "C", "D", "F"], "feedback": {"A": "Correct — within the 12-hour post-anaesthetic window.", "B": "Incorrect — chronic and long-established.", "C": "Correct — changing assessments are the core signal of instability.", "D": "Correct — newly admitted, under 24 hours.", "E": "Incorrect — ready for discharge is a stability marker.", "F": "Correct — an INR in the 4s is a dangerous derangement."}}$j$::jsonb,
   'Prioritization', 'Rules 1–3 combined', 'Medium',
   ARRAY['prioritization', 'four-rules', 'stability']::text[], 4)
ON CONFLICT (item_id) DO UPDATE SET
  question_type = EXCLUDED.question_type, stem = EXCLUDED.stem,
  rationale = EXCLUDED.rationale, content = EXCLUDED.content,
  correct = EXCLUDED.correct, topic = EXCLUDED.topic,
  subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty,
