  is_published = TRUE, updated_at = NOW();

-- items NCLEX_TUT_MCQ_00110 .. NCLEX_TUT_MCQ_00113
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks)
VALUES
  ('NCLEX_TUT_MCQ_00110', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A client is 11 hours post-operative following a general anaesthetic. How should the nurse classify this client?',
   'Twelve hours is the boundary. At 11 hours the client is still classed as fresh post-op and unstable regardless of how well they look — the risk of haemorrhage and anaesthetic complications has not yet passed.',
   $j${"options": [{"id": "A", "text": "Stable, because the surgery was completed and the client is awake"}, {"id": "B", "text": "Unstable, because the client is within 12 hours of a general anaesthetic"}, {"id": "C", "text": "Stable, because the anaesthetic has worn off by 8 hours"}, {"id": "D", "text": "Unstable only if the vital signs are abnormal"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — being awake does not end the 12-hour window.", "B": "Correct — 11 hours is inside the window.", "C": "Incorrect — the rule is 12 hours, not 8.", "D": "Incorrect — the classification does not wait for abnormal vitals."}}$j$::jsonb,
   'Prioritization', 'Rule 2 — fresh post-op', 'Easy',
   ARRAY['prioritization', 'post-op']::text[], 1),
  ('NCLEX_TUT_MCQ_00111', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Which client should the nurse assess first?',
   'The lower temperature belongs to the sicker client. Fever is expected in meningitis and has been unchanged for three days; fever is entirely unexpected in irritable bowel syndrome, it has just spiked, and it is a change. Three signals of instability beat one frightening diagnosis.',
   $j${"options": [{"id": "A", "text": "A 16-year-old with meningococcal meningitis whose temperature has been 39.9 °C since admission three days ago"}, {"id": "B", "text": "A 67-year-old with irritable bowel syndrome who spiked a temperature of 39.7 °C this afternoon"}, {"id": "C", "text": "A 24-year-old with a migraine requesting a darkened room"}, {"id": "D", "text": "A 50-year-old with hypothyroidism awaiting a repeat TSH"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — expected, unchanged, and admitted over 24 hours ago.", "B": "Correct — unexpected for the diagnosis, newly spiked, changing.", "C": "Incorrect — expected for migraine.", "D": "Incorrect — chronic and waiting on a routine result."}}$j$::jsonb,
   'Prioritization', 'Expected vs unexpected', 'Hard',
   ARRAY['prioritization', 'stability']::text[], 1),
  ('NCLEX_TUT_SATA_00103', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which findings always classify a client as unstable, even when they are expected for that client''s diagnosis? Select all that apply.',
   'Four findings override ''expected'': haemorrhage, fever above 105 °F, hypoglycaemia and being pulseless or breathless. Note that haemorrhage is not the same as bleeding — drain output is expected after surgery — and a haemoglobin of 9.4 is a mild derangement, not a critical one.',
   $j${"options": [{"id": "A", "text": "Haemorrhage"}, {"id": "B", "text": "A temperature above 40.6 °C (105 °F)"}, {"id": "C", "text": "Hypoglycaemia"}, {"id": "D", "text": "Pulseless or breathless"}, {"id": "E", "text": "Bleeding from a surgical drain"}, {"id": "F", "text": "A haemoglobin of 9.4 g/dL"}]}$j$::jsonb,
   $j${"answers": ["A", "B", "C", "D"], "feedback": {"A": "Correct — always unstable.", "B": "Correct — seizure risk.", "C": "Correct — risk of brain injury.", "D": "Correct — always unstable in the clinical setting.", "E": "Incorrect — bleeding is not haemorrhage; drain output is expected.", "F": "Incorrect — haemoglobin 8 to 11 is a mild abnormality."}}$j$::jsonb,
   'Prioritization', 'Always unstable', 'Medium',
   ARRAY['prioritization', 'stability']::text[], 4),
  ('NCLEX_TUT_MCQ_00112', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse arrives at the scene of an unwitnessed road accident. Four casualties are present. Which should the nurse attend to LAST?',
   'This is the field exception. In hospital, pulseless and breathless is always the highest priority. At the scene of an UNWITNESSED accident, a pulseless, breathless casualty is presumed dead and becomes the lowest priority — resources go to those who can still be saved.',
   $j${"options": [{"id": "A", "text": "A casualty with an open femoral fracture and heavy bleeding"}, {"id": "B", "text": "A casualty who is pulseless and not breathing"}, {"id": "C", "text": "A casualty with laboured breathing and chest bruising"}, {"id": "D", "text": "A casualty who is confused and repeating questions"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — heavy bleeding is salvageable and urgent.", "B": "Correct — unwitnessed arrest in the field. Presumed dead.", "C": "Incorrect — a breathing problem that can be treated.", "D": "Incorrect — confusion suggests a head injury worth attending."}}$j$::jsonb,
   'Prioritization', 'Field triage', 'Hard',
   ARRAY['prioritization', 'triage', 'emergency']::text[], 1),
  ('NCLEX_TUT_SATA_00104', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'During a mass-casualty incident, which findings would result in a client being tagged BLACK? Select all that apply.',
   'Black tags mark the expectant — treated last. Pulseless, breathless, and fixed and dilated pupils each earn one, and the third applies even when the casualty is still breathing. Bilateral fractures and a chest wound are survivable with treatment and would be tagged for care.',
   $j${"options": [{"id": "A", "text": "Pulseless"}, {"id": "B", "text": "Breathless"}, {"id": "C", "text": "Fixed and dilated pupils, though still breathing"}, {"id": "D", "text": "An open fracture of both legs"}, {"id": "E", "text": "A respiratory rate of 34 with an open chest wound"}]}$j$::jsonb,
   $j${"answers": ["A", "B", "C"], "feedback": {"A": "Correct.", "B": "Correct.", "C": "Correct — this one catches people, because they are still breathing.", "D": "Incorrect — serious, but survivable.", "E": "Incorrect — urgent and treatable; this is a red tag."}}$j$::jsonb,
   'Prioritization', 'Mass casualty triage', 'Medium',
   ARRAY['prioritization', 'triage', 'disaster']::text[], 3),
  ('NCLEX_TUT_MCQ_00113', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A client with angina pectoris reports chest pain that is not relieved by rest. How should the nurse classify this client?',
   'Angina pain that stops with rest is expected and therefore stable. Pain that does not stop with rest has broken the expected pattern — this is unstable angina and may be an evolving infarction.',
   $j${"options": [{"id": "A", "text": "Stable, because chest pain is expected in angina"}, {"id": "B", "text": "Unstable, because pain unrelieved by rest is not the expected pattern"}, {"id": "C", "text": "Stable, because the client has a known cardiac diagnosis"}, {"id": "D", "text": "Unstable, because all cardiac clients are unstable"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — the pain is expected; failing to settle is not.", "B": "Correct — the pattern has changed.", "C": "Incorrect — a known diagnosis does not make a new pattern safe.", "D": "Incorrect — a cardiac diagnosis alone does not confer instability."}}$j$::jsonb,
   'Prioritization', 'Expected vs unexpected', 'Medium',
   ARRAY['prioritization', 'cardiac', 'stability']::text[], 1)
