-- items NCLEX_TUT_SATA_00105 .. NCLEX_TUT_MCQ_00117
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks)
VALUES
  ('NCLEX_TUT_SATA_00105', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which laboratory results should the nurse interpret as markers of an UNSTABLE client? Select all that apply.',
   'Dangerous derangements point to instability: potassium in the 6s, a pH in the 6s, and a critically low platelet count. Mildly abnormal values — haemoglobin between 8 and 11, a raised BUN, a raised haematocrit — sit in the stable group.',
   $j${"options": [{"id": "A", "text": "Potassium 6.4 mmol/L"}, {"id": "B", "text": "Haemoglobin 9.8 g/dL"}, {"id": "C", "text": "Arterial pH 6.9"}, {"id": "D", "text": "Blood urea nitrogen mildly raised"}, {"id": "E", "text": "Platelet count 22 × 10⁹/L"}, {"id": "F", "text": "Raised haematocrit"}]}$j$::jsonb,
   $j${"answers": ["A", "C", "E"], "feedback": {"A": "Correct — potassium in the 6s risks fatal arrhythmia.", "B": "Incorrect — haemoglobin 8 to 11 is a mild abnormality.", "C": "Correct — a pH in the 6s is incompatible with stability.", "D": "Incorrect — a mildly raised BUN is a stable-range abnormality.", "E": "Correct — a critically low platelet count risks spontaneous bleeding.", "F": "Incorrect — a raised haematocrit is a mild abnormality."}}$j$::jsonb,
   'Prioritization', 'Lab values and stability', 'Medium',
   ARRAY['prioritization', 'labs', 'stability']::text[], 3),
  ('NCLEX_TUT_MCQ_00114', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Which client should the nurse see first?',
   'Hypoglycaemia is one of the four findings that always confers instability, because it can cause brain injury within minutes. Everything else here is chronic, unchanged, or expected for the diagnosis.',
   $j${"options": [{"id": "A", "text": "A client admitted 2 days ago with cellulitis whose redness is unchanged"}, {"id": "B", "text": "A client with type 1 diabetes whose blood glucose is 2.6 mmol/L"}, {"id": "C", "text": "A client with a chronic pressure ulcer due for review"}, {"id": "D", "text": "A client with COPD who is short of breath on exertion, as usual"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — unchanged over two days.", "B": "Correct — hypoglycaemia is always unstable.", "C": "Incorrect — chronic and scheduled.", "D": "Incorrect — 'as usual' is the giveaway. Expected."}}$j$::jsonb,
   'Prioritization', 'Always unstable', 'Easy',
   ARRAY['prioritization', 'endocrine', 'stability']::text[], 1),
  ('NCLEX_TUT_MCQ_00115', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse is prioritising four clients. Which is the MOST stable?',
   'Chronic, unchanged and expected — three stability markers at once. A new diagnosis, a changing assessment and a fresh post-operative client all sit in the unstable group.',
   $j${"options": [{"id": "A", "text": "A client newly diagnosed with lupus this morning"}, {"id": "B", "text": "A client whose assessment findings have changed since the last round"}, {"id": "C", "text": "A client with rheumatoid arthritis whose joint pain is at its usual level"}, {"id": "D", "text": "A client who returned from theatre 5 hours ago"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — newly diagnosed is an instability marker.", "B": "Incorrect — changing assessment is the core instability signal.", "C": "Correct — chronic, unchanged, expected.", "D": "Incorrect — under 12 hours post-op."}}$j$::jsonb,
   'Prioritization', 'Stable vs unstable', 'Easy',
   ARRAY['prioritization', 'stability']::text[], 1),
  ('NCLEX_TUT_SATA_00106', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which tasks may a registered nurse delegate to a licensed practical nurse (LPN/LVN)? Select all that apply.',
   'An LPN may maintain an existing IV, reinforce teaching already given, and repeat a task the RN has performed once. They may not start IVs, administer blood, or carry out an admission assessment.',
   $j${"options": [{"id": "A", "text": "Starting a peripheral IV on a newly admitted client"}, {"id": "B", "text": "Monitoring an already-running IV infusion and documenting the flow rate"}, {"id": "C", "text": "Reinforcing teaching the RN has already delivered about a low-sodium diet"}, {"id": "D", "text": "Changing a post-operative dressing that the RN changed for the first time yesterday"}, {"id": "E", "text": "Administering a unit of packed red cells"}, {"id": "F", "text": "Completing the admission assessment on a new arrival"}]}$j$::jsonb,
   $j${"answers": ["B", "C", "D"], "feedback": {"A": "Incorrect — LPNs cannot start an IV.", "B": "Correct — maintaining is permitted; starting is not.", "C": "Correct — reinforcing is permitted; teaching is not.", "D": "Correct — the RN did the first, so the LPN may do the rest.", "E": "Incorrect — blood administration is outside LPN scope.", "F": "Incorrect — admission assessment belongs to the RN."}}$j$::jsonb,
   'Delegation', 'LPN scope', 'Medium',
   ARRAY['delegation', 'scope-of-practice']::text[], 3),
  ('NCLEX_TUT_MCQ_00116', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A client returned from theatre this morning. Who should perform the first post-operative dressing change?',
   'Two separate rules make this the RN''s task. An LPN cannot perform the first of anything, and an LPN cannot care for an unstable client — a client operated on this morning is inside the 12-hour window.',
   $j${"options": [{"id": "A", "text": "The LPN, because dressing changes are within their scope"}, {"id": "B", "text": "The registered nurse, because it is the first dressing change and the client is fresh post-op"}, {"id": "C", "text": "The unlicensed assistive personnel, under supervision"}, {"id": "D", "text": "Either the RN or the LPN, depending on the workload"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — dressing changes are, but not the FIRST one.", "B": "Correct — first of anything, and an unstable client.", "C": "Incorrect — well outside UAP scope.", "D": "Incorrect — workload never expands a scope of practice."}}$j$::jsonb,
   'Delegation', 'First of anything', 'Medium',
   ARRAY['delegation', 'post-op']::text[], 1),
  ('NCLEX_TUT_MCQ_00117', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'An unlicensed assistive personnel (UAP) asks which entry they may make in a client''s record. Which response by the nurse is correct?',
   'A UAP may chart what they did — a task performed, a safety measure put in place. They may not chart anything that interprets the client''s condition, because interpretation is assessment.',
   $j${"options": [{"id": "A", "text": "'You may document that the client tolerated ambulation well.'"}, {"id": "B", "text": "'You may document that the side rail is up and the bed is lowered.'"}, {"id": "C", "text": "'You may document that the client appears less anxious today.'"}, {"id": "D", "text": "'You may document your assessment of the client's wound.'"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — 'tolerated well' is an evaluation of response.", "B": "Correct — a factual record of what the UAP did.", "C": "Incorrect — 'less anxious' is a judgement about the client.", "D": "Incorrect — UAPs do not assess or document assessments."}}$j$::jsonb,
   'Delegation', 'UAP scope', 'Easy',
   ARRAY['delegation', 'documentation']::text[], 1)
