-- items NCLEX_TUT_SATA_00107 .. NCLEX_TUT_MCQ_00121
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks)
VALUES
  ('NCLEX_TUT_SATA_00107', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which medications may a UAP apply to a client, within the usual scope of the role? Select all that apply.',
   'A UAP may apply topical, over-the-counter and barrier preparations only. Nitroglycerin, Neosporin and hydrocortisone cream are all prescription or medicated products, whatever their route.',
   $j${"options": [{"id": "A", "text": "A&D barrier ointment to intact perineal skin"}, {"id": "B", "text": "Nitroglycerin ointment to the chest wall"}, {"id": "C", "text": "An over-the-counter moisturising cream"}, {"id": "D", "text": "Hydrocortisone 1% cream to a rash"}, {"id": "E", "text": "Neosporin ointment to a superficial graze"}]}$j$::jsonb,
   $j${"answers": ["A", "C"], "feedback": {"A": "Correct — a barrier preparation.", "B": "Incorrect — nitroglycerin is a potent cardiac drug.", "C": "Correct — over the counter and not medicated.", "D": "Incorrect — a medicated steroid preparation.", "E": "Incorrect — an antibiotic preparation, not OTC in this context."}}$j$::jsonb,
   'Delegation', 'UAP scope', 'Hard',
   ARRAY['delegation', 'medication']::text[], 2),
  ('NCLEX_TUT_MCQ_00118', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse reports hearing new crackles in a client''s chest. Who should assess the client?',
   'An LPN may not perform the first assessment after a change in condition. New crackles are exactly that change, so the RN assesses.',
   $j${"options": [{"id": "A", "text": "The LPN, because auscultation is within their scope"}, {"id": "B", "text": "The registered nurse, because this is a new change in the client's condition"}, {"id": "C", "text": "The UAP, who can take a set of vital signs first"}, {"id": "D", "text": "The respiratory therapist, without nursing assessment"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — the restriction is not about the skill but about the first assessment after a change.", "B": "Correct — a new finding requires the RN.", "C": "Incorrect — vital signs do not substitute for an assessment.", "D": "Incorrect — the nurse does not hand off her own assessment."}}$j$::jsonb,
   'Delegation', 'LPN scope', 'Medium',
   ARRAY['delegation', 'assessment']::text[], 1),
  ('NCLEX_TUT_MCQ_00119', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A client''s son says, ''Please leave Dad''s restraints off — I''ll call you before I leave the ward.'' What is the nurse''s best response?',
   'Safety cannot be delegated to an untrained family member, however well-meaning. The correct response declines the delegation without dismissing the son — and restraint use should always be under review.',
   $j${"options": [{"id": "A", "text": "'That's fine, as long as you let me know before you go.'"}, {"id": "B", "text": "'I can't hand over responsibility for your father's safety, but let's talk about whether he still needs them.'"}, {"id": "C", "text": "'Only if you sign a form taking responsibility.'"}, {"id": "D", "text": "'Restraints must stay on at all times once prescribed.'"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — this delegates a safety responsibility.", "B": "Correct — declines the handover and opens the clinical question.", "C": "Incorrect — a signature does not transfer a nursing responsibility.", "D": "Incorrect — restraints are reviewed and removed at the earliest safe opportunity."}}$j$::jsonb,
   'Delegation', 'Family and visitors', 'Medium',
   ARRAY['delegation', 'safety', 'restraints']::text[], 1),
  ('NCLEX_TUT_MCQ_00120', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'The mother of a 3-year-old newly diagnosed with type 1 diabetes asks whether she may give her child''s insulin injections at home. What is the nurse''s best response?',
   'A taught family member can hold a responsibility an untaught one cannot. Teaching plus documentation of what was taught is what makes the delegation safe and defensible.',
   $j${"options": [{"id": "A", "text": "'No — insulin must be given by a licensed professional.'"}, {"id": "B", "text": "'Yes — once I have taught you the technique and documented that teaching.'"}, {"id": "C", "text": "'Yes — parents may always administer their own child's medications.'"}, {"id": "D", "text": "'Only if a district nurse supervises every dose.'"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — parents routinely give insulin at home.", "B": "Correct — teach, then document what you taught.", "C": "Incorrect — 'always' skips the teaching requirement.", "D": "Incorrect — supervision of every dose is neither required nor practical."}}$j$::jsonb,
   'Delegation', 'Family and visitors', 'Medium',
   ARRAY['delegation', 'teaching', 'paediatrics']::text[], 1),
  ('NCLEX_TUT_SATA_00108', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which tasks may the registered nurse delegate to a UAP? Select all that apply.',
   'Vital signs, blood-glucose checks and enemas are the named exceptions to the UAP restrictions on assessment and treatment, and an established ADL may be delegated. Evaluating a response is RN work, and no UAP performs the first feeding of a client with a swallowing risk.',
   $j${"options": [{"id": "A", "text": "Taking a set of vital signs on a stable client"}, {"id": "B", "text": "Performing a blood-glucose check on a client with diabetes"}, {"id": "C", "text": "Administering a soap-suds enema"}, {"id": "D", "text": "Assisting a client to shower who has showered with help before"}, {"id": "E", "text": "Evaluating whether pain medication has been effective"}, {"id": "F", "text": "Feeding a stroke client for the first time since admission"}]}$j$::jsonb,
   $j${"answers": ["A", "B", "C", "D"], "feedback": {"A": "Correct — vital signs are the assessment exception.", "B": "Correct — blood-glucose checks are permitted.", "C": "Correct — enemas are the treatment exception.", "D": "Correct — an ADL the client has done with help before.", "E": "Incorrect — evaluation belongs to the RN.", "F": "Incorrect — never the first of anything, and aspiration risk."}}$j$::jsonb,
   'Delegation', 'UAP scope', 'Hard',
   ARRAY['delegation', 'scope-of-practice']::text[], 4),
  ('NCLEX_TUT_MCQ_00121', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse suspects that a colleague has been diverting narcotics from the ward stock. What should the nurse do?',
   'Diversion is illegal. Illegal acts go to the supervisor — the nurse does not investigate, confront, or wait for certainty.',
   $j${"options": [{"id": "A", "text": "Confront the colleague privately and ask for an explanation"}, {"id": "B", "text": "Report the concern to the supervisor"}, {"id": "C", "text": "Wait and gather more evidence before acting"}, {"id": "D", "text": "Document the concern in the client's record"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — confrontation is for immediate harm, not illegality.", "B": "Correct — illegal act, so report it up.", "C": "Incorrect — waiting allows the diversion to continue.", "D": "Incorrect — a staffing concern never goes in a client's record."}}$j$::jsonb,
   'Staff management', 'Illegal acts', 'Easy',
   ARRAY['staff-management', 'legal-ethical']::text[], 1)
