-- items NCLEX_TUT_MCQ_00122 .. NCLEX_TUT_MCQ_00127
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks)
VALUES
  ('NCLEX_TUT_MCQ_00122', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse observes an aide providing perineal care to a client without wearing gloves. What is the nurse''s best action?',
   'Nothing illegal has happened, but someone is at immediate risk of harm — both the client and the aide. Immediate harm means confront and take over the task now, not later.',
   $j${"options": [{"id": "A", "text": "Report the aide to the unit supervisor at the end of the shift"}, {"id": "B", "text": "Intervene immediately and take over the task"}, {"id": "C", "text": "Mention it to the aide at the next team meeting"}, {"id": "D", "text": "Take no action, as the aide has completed this task many times"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — the harm is happening now; the end of the shift is too late.", "B": "Correct — immediate physical harm means intervene now.", "C": "Incorrect — 'talk later' is for behaviour that harms nobody.", "D": "Incorrect — inaction is never the answer."}}$j$::jsonb,
   'Staff management', 'Immediate harm', 'Medium',
   ARRAY['staff-management', 'infection-control']::text[], 1),
  ('NCLEX_TUT_MCQ_00123', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'During every handover, a colleague mispronounces ''exacerbation'' as ''exasperation''. What should the nurse do?',
   'Nothing illegal, nobody in harm''s way — this is simply unprofessional. That combination means a private conversation later. Note that ''ignore it'' remains wrong even when the behaviour is trivial.',
   $j${"options": [{"id": "A", "text": "Correct the colleague in front of the team so everyone learns"}, {"id": "B", "text": "Report the colleague to the supervisor"}, {"id": "C", "text": "Speak to the colleague privately at a later time"}, {"id": "D", "text": "Ignore it, as it does not affect client care"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — public correction is humiliating and unnecessary.", "B": "Incorrect — this does not warrant escalation.", "C": "Correct — inappropriate but harmless, so address it privately later.", "D": "Incorrect — ignoring inappropriate behaviour is never the answer."}}$j$::jsonb,
   'Staff management', 'Unprofessional behaviour', 'Easy',
   ARRAY['staff-management']::text[], 1),
  ('NCLEX_TUT_MCQ_00124', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse observes a colleague administering a medication by a route that is not prescribed, and the client is beginning to react. What should the nurse do FIRST?',
   'When an act is both wrong and actively harming the client, do both — but in the right order. Take over the task and attend to the client first, then report. The client comes before the paperwork.',
   $j${"options": [{"id": "A", "text": "Report the incident to the supervisor"}, {"id": "B", "text": "Complete an incident report"}, {"id": "C", "text": "Take over the client's care immediately, then report the incident"}, {"id": "D", "text": "Ask the colleague to explain their reasoning"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — reporting first leaves the client reacting.", "B": "Incorrect — documentation follows the clinical response.", "C": "Correct — protect the client, then escalate.", "D": "Incorrect — this is not the moment for a discussion."}}$j$::jsonb,
   'Staff management', 'Immediate harm', 'Hard',
   ARRAY['staff-management', 'medication-safety']::text[], 1),
  ('NCLEX_TUT_MCQ_00125', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A client has been admitted following a suicide attempt. Which nursing action is the highest priority?',
   'Ask what happens if each action is omitted. No anxiolytic — agitated. No orientation — lost. No introductions — knows nobody. No suicide precautions — dead. The omission with the worst consequence is the priority.',
   $j${"options": [{"id": "A", "text": "Administering the prescribed anxiolytic"}, {"id": "B", "text": "Orienting the client to the unit"}, {"id": "C", "text": "Initiating suicide precautions"}, {"id": "D", "text": "Introducing the client to the staff on duty"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — omission causes agitation, not death.", "B": "Incorrect — omission causes disorientation.", "C": "Correct — the only omission here that is fatal.", "D": "Incorrect — omission causes unfamiliarity."}}$j$::jsonb,
   'Staff management', 'Worst-consequences reasoning', 'Medium',
   ARRAY['prioritization', 'psychosocial', 'safety']::text[], 1),
  ('NCLEX_TUT_MCQ_00126', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse walks into a room and finds two adult clients engaged in consensual sexual activity. What is the nurse''s best action?',
   'Consenting adults are entitled to privacy and there is no safety concern to answer. The same applies to a client masturbating in their own room.',
   $j${"options": [{"id": "A", "text": "Separate the clients and report them to the supervisor"}, {"id": "B", "text": "Close the door and give them privacy"}, {"id": "C", "text": "Remain in the room to ensure nobody is harmed"}, {"id": "D", "text": "Document the incident in both clients' records"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — there is nothing to report.", "B": "Correct — close the door and leave them to it.", "C": "Incorrect — remaining is the intrusion, not the safeguard.", "D": "Incorrect — no clinical event has occurred."}}$j$::jsonb,
   'Staff management', 'Client rights', 'Medium',
   ARRAY['staff-management', 'psychosocial', 'client-rights']::text[], 1),
  ('NCLEX_TUT_MCQ_00127', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse on a surgical unit receives handover for four clients. Which client should the nurse assess first?',
   'Fresh post-op at 3 hours, and the modifying phrase describes a new airway threat — increasing difficulty swallowing after thyroid surgery suggests a developing haematoma. Drain output at 18 hours is expected, chronic pancreatitis pain is expected, and a client awaiting discharge is stable.',
   $j${"options": [{"id": "A", "text": "A client 18 hours after a hemicolectomy whose wound drain has drained 40 mL of serosanguineous fluid"}, {"id": "B", "text": "A client 3 hours after a thyroidectomy who reports increasing difficulty swallowing"}, {"id": "C", "text": "A client with chronic pancreatitis reporting epigastric pain"}, {"id": "D", "text": "A client awaiting discharge after an uncomplicated appendicectomy"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — expected drainage, and past the 12-hour window.", "B": "Correct — fresh post-op with an unexpected, airway-threatening change.", "C": "Incorrect — expected for the diagnosis, and chronic.", "D": "Incorrect — the most stable client on the list."}}$j$::jsonb,
   'Prioritization', 'Mixed', 'Hard',
   ARRAY['prioritization', 'post-op']::text[], 1)
