-- items NCLEX_TUT_SATA_00109 .. NCLEX_TUT_MCQ_00131
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks)
VALUES
  ('NCLEX_TUT_SATA_00109', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'A charge nurse is planning assignments. Which tasks require a registered nurse and cannot be delegated? Select all that apply.',
   'Plan, teach, evaluate and assess are the four RN verbs. Recording intake and transporting a stable client are routine tasks a UAP may carry out.',
   $j${"options": [{"id": "A", "text": "Developing the plan of care for a newly admitted client"}, {"id": "B", "text": "Recording the oral intake of a stable client"}, {"id": "C", "text": "Teaching a client to self-administer a new inhaler"}, {"id": "D", "text": "Evaluating whether a client's pain has responded to analgesia"}, {"id": "E", "text": "Transporting a stable client to the radiology department"}, {"id": "F", "text": "Performing the admission assessment"}]}$j$::jsonb,
   $j${"answers": ["A", "C", "D", "F"], "feedback": {"A": "Correct — care planning is RN work.", "B": "Incorrect — recording intake may be delegated.", "C": "Correct — teaching cannot be delegated, only reinforced.", "D": "Correct — evaluation is RN work.", "E": "Incorrect — transporting a stable client may be delegated.", "F": "Correct — admission assessment is RN work."}}$j$::jsonb,
   'Delegation', 'Mixed', 'Medium',
   ARRAY['delegation', 'scope-of-practice']::text[], 4),
  ('NCLEX_TUT_MCQ_00128', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'An emergency department is receiving casualties from a building collapse. Which casualty should be tagged for treatment LAST?',
   'Fixed and dilated pupils earn a black tag even when the casualty is still breathing. In a mass-casualty incident, resources go to those who can be saved. The walking wounded are treated last among the LIVING, but the expectant casualty is treated after them.',
   $j${"options": [{"id": "A", "text": "A casualty with an open femur fracture, alert, pulse 118"}, {"id": "B", "text": "A casualty who is breathing at 8 breaths per minute with fixed and dilated pupils"}, {"id": "C", "text": "A casualty with partial-thickness burns to both forearms"}, {"id": "D", "text": "A casualty with an obvious wrist fracture, walking and talking"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — urgent and salvageable.", "B": "Correct — fixed and dilated pupils means expectant, black tag.", "C": "Incorrect — treatable, and not immediately life-threatening.", "D": "Incorrect — minor injury, but still ahead of an expectant casualty."}}$j$::jsonb,
   'Prioritization', 'Mixed', 'Hard',
   ARRAY['triage', 'disaster']::text[], 1),
  ('NCLEX_TUT_MCQ_00129', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Which client is the LOWEST priority for the nurse to assess?',
   'The sickle cell client''s pain is expected for their diagnosis, unchanged, and they were admitted more than 24 hours ago — three stability markers. The other three all describe a change from baseline.',
   $j${"options": [{"id": "A", "text": "A client with sickle cell disease reporting the joint pain typical of their usual crises, admitted two days ago"}, {"id": "B", "text": "A client with a new onset of slurred speech"}, {"id": "C", "text": "A client whose urine output has fallen to 15 mL/hour"}, {"id": "D", "text": "A client whose oxygen saturation has dropped from 96% to 88%"}]}$j$::jsonb,
   $j${"answer": "A", "feedback": {"A": "Correct — expected, unchanged, and settled.", "B": "Incorrect — new slurred speech is a brain finding and highly urgent.", "C": "Incorrect — falling urine output is a change.", "D": "Incorrect — a dropping saturation is a change."}}$j$::jsonb,
   'Prioritization', 'Mixed', 'Medium',
   ARRAY['prioritization', 'stability']::text[], 1),
  ('NCLEX_TUT_MCQ_00130', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse observes a student nurse about to disconnect a client''s oxygen to take them for a walk. The client has an oxygen saturation of 89% on 2 L/min. What should the nurse do?',
   'Nothing illegal is happening, but the client is about to come to immediate physical harm. Immediate harm means confront and take over now, not report later.',
   $j${"options": [{"id": "A", "text": "Report the student to the clinical instructor after the shift"}, {"id": "B", "text": "Intervene immediately and take over the client's care"}, {"id": "C", "text": "Allow the walk and monitor the client closely"}, {"id": "D", "text": "Document the student's behaviour in the client's record"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — the harm would happen before the shift ends.", "B": "Correct — immediate harm, so intervene now.", "C": "Incorrect — a saturation of 89% off oxygen is not safe to trial.", "D": "Incorrect — staff conduct never goes in a client's record."}}$j$::jsonb,
   'Staff management', 'Mixed', 'Medium',
   ARRAY['staff-management', 'safety']::text[], 1),
  ('NCLEX_TUT_SATA_00110', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which clients should the nurse classify as UNSTABLE? Select all that apply.',
   'Within 12 hours of general anaesthesia, hypoglycaemia, and admission under 24 hours with an acute complaint all indicate instability. A haemoglobin of 10.2 is a mild abnormality, unchanged breathlessness in COPD is expected, and a client going home today is stable.',
   $j${"options": [{"id": "A", "text": "A client 4 hours after a general anaesthetic"}, {"id": "B", "text": "A client with a haemoglobin of 10.2 g/dL and no active bleeding"}, {"id": "C", "text": "A client whose blood glucose is 2.8 mmol/L"}, {"id": "D", "text": "A client with COPD whose breathlessness is unchanged from admission"}, {"id": "E", "text": "A client admitted 90 minutes ago with chest pain"}, {"id": "F", "text": "A client with a chronic leg ulcer being discharged this afternoon"}]}$j$::jsonb,
   $j${"answers": ["A", "C", "E"], "feedback": {"A": "Correct — inside the 12-hour anaesthetic window.", "B": "Incorrect — haemoglobin 8 to 11 is a mild derangement.", "C": "Correct — hypoglycaemia is always unstable.", "D": "Incorrect — unchanged and expected.", "E": "Correct — newly admitted with an acute complaint.", "F": "Incorrect — ready for discharge."}}$j$::jsonb,
   'Prioritization', 'Mixed', 'Medium',
   ARRAY['prioritization', 'stability']::text[], 3),
  ('NCLEX_TUT_MCQ_00131', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A registered nurse is assigning clients to an LPN. Which client is the most appropriate assignment?',
   'The LPN may repeat a task the RN has already performed once, on a stable client. Admission assessment, IV medication and teaching are all outside LPN scope.',
   $j${"options": [{"id": "A", "text": "A client admitted an hour ago requiring an admission assessment"}, {"id": "B", "text": "A client requiring their first dose of IV antibiotics"}, {"id": "C", "text": "A client with stable heart failure requiring a routine dressing change the RN performed yesterday"}, {"id": "D", "text": "A client requiring teaching before discharge tomorrow"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — admission assessments belong to the RN.", "B": "Incorrect — LPNs cannot hang or push IV medications.", "C": "Correct — stable client, and not the first of anything.", "D": "Incorrect — LPNs reinforce teaching, they do not deliver it."}}$j$::jsonb,
   'Delegation', 'Mixed', 'Medium',
   ARRAY['delegation', 'assignment']::text[], 1)
