   $j${"answer": "A", "feedback": {"A": "Correct — confusion is a brain finding, and brain ranks first.", "B": "Incorrect — heart ranks third.", "C": "Incorrect — kidney ranks fifth.", "D": "Incorrect — pancreas ranks last."}}$j$::jsonb,
