-- ====================================================================
-- 4. Programme, modules, blocks
-- ====================================================================
-- The AFTER INSERT trigger nclex_programmes_seed_units_trg creates
-- length_units blank units with random ids on every programme INSERT;
-- they collide with deterministic ones on (programme_id, unit_index).
-- Drop the trigger's rows before inserting ours. On a re-run there is
-- nothing to drop — the INSERT hits ON CONFLICT and the trigger never fires.

INSERT INTO nclex_programmes (
  programme_id, tutor_id, title, tagline, description,
  delivery_mode, unit_label, length_units,
  price_currency, show_price_publicly, payment_collection_mode,
  access_window_days, payment_gates_access, status, published_at
) VALUES (
  '60000000-0000-4000-8000-000000000001', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'NCLEX Prioritization Crash Course',
  'Five short modules on the section most candidates guess at — prioritization, delegation and staff management.',
  'There will be at least fifteen prioritization and delegation questions on your exam, and most candidates guess at every one of them. They are the most guessable questions on the paper and the most learnable — the rules are short, they are fixed, and they do not require you to know more medicine than you already do.

This is a short, self-paced course covering exactly that section. Five modules, each one a single sitting: read the notes, then drill them while the framework is still in your head. There is a timed mock at the end made of questions you have not seen.

What you will come away with: how to tell whether an item wants your sickest client or your healthiest one; how to strip an answer choice down to the part that decides it; the four ranking rules and the organ tie-breaker for when they run out; the vocabulary that separates a stable client from an unstable one; what an LPN, a UAP and a family member may each be given; and what to do when a colleague does something they should not have.

Who this is for: anyone sitting NCLEX-RN who loses marks on "which client would you see first". You can take it at any point in your preparation — early, so you drill the rest of your revision with the framework already in place, or late, as a targeted repair. It assumes you have basic clinical knowledge; it teaches you what to do with it.

Self-paced, so there are no live sessions and no fixed dates. Ninety days of access from the day you enrol.',
  'SELF_PACED', 'MODULE', 5,
  'GHS', TRUE, 'ON_PLATFORM',
  90, TRUE, 'PUBLISHED', NOW()
)
ON CONFLICT (programme_id) DO UPDATE SET
  title = EXCLUDED.title, tagline = EXCLUDED.tagline,
  description = EXCLUDED.description,
  delivery_mode = EXCLUDED.delivery_mode, unit_label = EXCLUDED.unit_label,
  length_units = EXCLUDED.length_units,
  access_window_days = EXCLUDED.access_window_days,
  status = EXCLUDED.status, updated_at = NOW();

